sp_DeletarCliente	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_DeletarCliente`(\n\n    IN p_idCliente INT\n\n)\nBEGIN\n\n    UPDATE Cliente SET fAtivo = CASE WHEN fAtivo = 1 THEN 0 ELSE 1 END WHERE idCliente = p_idCliente;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
